class METSalesPickingListGenerationTaskController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>Constuct new object</summary>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METSalesPickingListGenerationTaskController();
        controller.parmExecutionMode(_executionMode);        
        controller.parmLoadFromSysLastValue(false); // parameters are set via code

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METSalesPickingListGenerationTaskService), methodstr(METSalesPickingListGenerationTaskService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>Main method</summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METSalesPickingListGenerationTaskController controller = METSalesPickingListGenerationTaskController::construct();
    controller.startOperation();
}

    /// <summary>
    /// Description
    /// </summary>
    /// <returns>Generate purchase orders</returns>
    public ClassDescription defaultCaption()
    {
        METSalesPickingListGenerationTaskContract   dataContract;

        if(this.getDataContractObject() != null)
        {
            dataContract = this.getDataContractObject();

            return dataContract.getCaption();
        }
        else
        {
            return "@MET:MetPickingListGenerationTask";
        }
    }
